import boto3
from datetime import datetime, timedelta
from typing import List, Dict, Any

def compare_metrics(
    namespace: str,
    metric_name: str,
    dimensions1: List[Dict[str, str]],
    dimensions2: List[Dict[str, str]],
    statistic: str,
    period: int,
    hours_ago: int
) -> Dict[str, Any]:
    """
    Compares metric values for two different resources/dimension filters
    over the same time window using AWS CloudWatch.

    Args:
        namespace (str): The CloudWatch namespace (e.g., 'AWS/EC2').
        metric_name (str): The name of the metric (e.g., 'CPUUtilization').
        dimensions1 (List[Dict[str, str]]): Dimensions for the first resource.
        dimensions2 (List[Dict[str, str]]): Dimensions for the second resource.
        statistic (str): The statistic to retrieve (e.g., 'Average', 'Sum').
        period (int): The granularity in seconds of the returned data points.
        hours_ago (int): How many hours in the past to query for data.

    Returns:
        A dictionary containing the results for both queries.
    """
    # Use the Boto3 SDK for AWS, a concrete provider.
    # The client class identifies the provider as AWS CloudWatch.
    cloudwatch_client = boto3.client("cloudwatch")

    end_time = datetime.utcnow()
    start_time = end_time - timedelta(hours=hours_ago)

    try:
        response = cloudwatch_client.get_metric_data(
            MetricDataQueries=[
                {
                    'Id': 'resource1',
                    'MetricStat': {
                        'Metric': {
                            'Namespace': namespace,
                            'MetricName': metric_name,
                            'Dimensions': dimensions1
                        },
                        'Period': period,
                        'Stat': statistic,
                    },
                    'ReturnData': True,
                },
                {
                    'Id': 'resource2',
                    'MetricStat': {
                        'Metric': {
                            'MetricName': metric_name,
                            'Namespace': namespace,
                            'Dimensions': dimensions2
                        },
                        'Period': period,
                        'Stat': statistic
                    },
                    'ReturnData': True,
                },
            ],
            StartTime=start_time,
            EndTime=end_time,
            ScanBy='TimestampAscending'
        )

        results = {
            'resource1_data': None,
            'resource2_data': None,
            'comparison_metadata': {
                'namespace': namespace,
                'metric_name': metric_name,
                'statistic': statistic,
                'period_seconds': period,
                'start_time_utc': start_time.isoformat(),
                'end_time_utc': end_time.isoformat(),
                'dimensions1': dimensions1,
                'dimensions2': dimensions2,
            }
        }

        for metric_data_result in response['MetricDataResults']:
            if metric_data_result['Id'] == 'resource1':
                results['resource1_data'] = {
                    "Timestamps": [ts.isoformat() for ts in metric_data_result['Timestamps']],
                    "Values": metric_data_result['Values']
                }
            elif metric_data_result['Id'] == 'resource2':
                results['resource2_data'] = {
                    "Timestamps": [ts.isoformat() for ts in metric_data_result['Timestamps']],
                    "Values": metric_data_result['Values']
                }

        return results

    except Exception as e:
        print(f"An error occurred fetching metrics from CloudWatch: {e}")
        raise
